      "2010 年年會上，德州長大的年輕白人**理查．史賓賽**（Richard Spencer）穿著毛呢外套、帶著蘋果筆電登台，剛創辦網路雜誌《另類右派》（The Alternative Right）。他描繪的未來與古聯盟相似：加州與西南部的拉丁裔民族主義社群、內陸城市的黑人社群、中西部的「基督教重建主義新教州」。他認為政治正走向裂解，應加速崩潰並做好準備。六年後，他在華府集會高喊把納粹口號英譯的「Hail Trump! Hail our people! Hail victory!」而惡名大噪；米塞斯研究院院長則寫道，川普凸顯「世界政府全球主義敘事中的裂痕」，自由意志主義者應善加利用，支持各種分離。",
      "羅斯巴德生前最後幾場演講之一在亞特蘭大外的農場，他想像北軍將領與總統雕像像東柏林列寧像一樣「傾倒崩壞」，南軍英雄紀念碑則在該立之處立起。2017 年 8 月，白人民族主義者為捍衛夏洛斯特維爾（Charlottesville）的羅伯．李伊雕像，穿著白色馬球衫與卡其褲、舉著火炬遊行，高喊「你們不會取代我們」。主辦人之一是霍普支持者，販售「I ♥ PHYSICAL REMOVAL」（我愛實際上的消除）保險桿貼紙。",
